import cartopy.crs as ccrs
import cartopy.feature as cfeature
from cartopy.mpl.gridliner import LONGITUDE_FORMATTER, LATITUDE_FORMATTER

from dict_inmet_stations import inmet


def read_stations(stations):
    """Extract code, name, lat, lon, alt arrays from the dictionary."""
    codes, names, lats, lons, alts = [], [], [], [], []
    for key, (code, name, lat, lon, alt) in stations.items():
        codes.append(code)
        names.append(name.strip())
        lats.append(lat)
        lons.append(lon)
        alts.append(alt)
    return (np.array(codes), np.array(names), np.array(lats),
            np.array(lons), np.array(alts))


def parse_file_ranges(file_list_str):
    """
    Parses start and end dates for each station code from the raw text list.
    """
    file_ranges = {}
    pattern = re.compile(r'dados_([A-Z0-9]+)_H_(\d{4}-\d{2}-\d{2})_(\d{4}-\d{2}-\d{2})\.csv')
    matches = pattern.findall(file_list_str)

    for code, start_str, end_str in matches:
        start_date = datetime.strptime(start_str, "%Y-%m-%d")
        end_date = datetime.strptime(end_str, "%Y-%m-%d")
        file_ranges[code] = (start_date, end_date)

    return file_ranges


def compute_missing_percentage_2000_2025(codes, file_ranges):
    """
    Computes the percentage of missing hourly data between 2000-01-01
    and 2025-12-31 for each station based on its active start and end dates.
    """
    target_start = datetime(2000, 1, 1)
    target_end = datetime(2025, 12, 31, 23)
    total_period_hours = int((target_end - target_start).total_seconds() / 3600) + 1

    missing_pcts = []

    for code in codes:
        if code in file_ranges:
            st_start, st_end = file_ranges[code]

            overlap_start = max(target_start, st_start)
            overlap_end = min(target_end, st_end)

            if overlap_start <= overlap_end:
                active_hours = (overlap_end - overlap_start).total_seconds() / 3600.0 + 1
            else:
                active_hours = 0.0

            missing_hours = total_period_hours - active_hours
            pct = (missing_hours / total_period_hours) * 100.0
            missing_pcts.append(np.clip(pct, 0.0, 100.0))
        else:
            missing_pcts.append(100.0)

    return np.array(missing_pcts)


